18	/**
19	 * Defines the severity level for user-facing feedback.
20	 * This maps loosely to UI `MessageType`
21	 */
22	export type FeedbackSeverity = 'info' | 'warning' | 'error';
23	
24	/**
25	 * Payload for the 'user-feedback' event.
26	 */
27	export interface UserFeedbackPayload {
28	  /**
29	   * The severity level determines how the message is rendered in the UI
30	   * (e.g. colored text, specific icon).
31	   */
32	  severity: FeedbackSeverity;
33	  /**
34	   * The main message to display to the user in the chat history or stdout.
35	   */
36	  message: string;
37	  /**
38	   * The original error object, if applicable.
39	   * Listeners can use this to extract stack traces for debug logging
40	   * or verbose output, while keeping the 'message' field clean for end users.
41	   */
42	  error?: unknown;
43	}
44	
45	/**
46	 * Payload for the 'model-changed' event.
47	 */
48	export interface ModelChangedPayload {
49	  /**
50	   * The new model that was set.
51	   */
52	  model: string;
53	}
54	
55	/**
56	 * Payload for the 'console-log' event.
57	 */
58	export interface ConsoleLogPayload {
59	  type: 'log' | 'warn' | 'error' | 'debug' | 'info';
60	  content: string;
61	}
62	
63	/**
64	 * Payload for the 'output' event.
65	 */
66	export interface OutputPayload {
67	  isStderr: boolean;
68	  chunk: Uint8Array | string;
69	  encoding?: BufferEncoding;
70	}
71	
72	/**
73	 * Payload for the 'memory-changed' event.
74	 */
75	export interface MemoryChangedPayload {
76	  fileCount: number;
77	}
78	
79	/**
80	 * Base payload for hook-related events.
81	 */
82	export interface HookPayload {
83	  hookName: string;
84	  eventName: string;
85	}
86	
87	/**
88	 * Payload for the 'hook-start' event.
89	 */
90	export interface HookStartPayload extends HookPayload {
91	  /**
92	   * The 1-based index of the current hook in the execution sequence.
93	   * Used for progress indication (e.g. "Hook 1/3").
94	   */
95	  hookIndex?: number;
96	  /**
97	   * The total number of hooks in the current execution sequence.
98	   */
99	  totalHooks?: number;
100	}
101	
102	/**
103	 * Payload for the 'hook-end' event.
104	 */
105	export interface HookEndPayload extends HookPayload {
106	  success: boolean;
107	}
108	
109	/**
110	 * Payload for the 'retry-attempt' event.
111	 */
112	export interface RetryAttemptPayload {
113	  attempt: number;
114	  maxAttempts: number;
115	  delayMs: number;
116	  error?: string;
117	  model: string;
118	}
119	
120	/**
121	 * Payload for the 'consent-request' event.
122	 */
123	export interface ConsentRequestPayload {
124	  prompt: string;
125	  onConfirm: (confirmed: boolean) => void;
126	}
127	
128	/**
129	 * Payload for the 'mcp-progress' event.
130	 */
131	export interface McpProgressPayload {
132	  serverName: string;
133	  callId: string;
134	  progressToken: string | number;
135	  progress: number;
136	  total?: number;
137	  message?: string;
138	}
139	
140	/**
141	 * Payload for the 'agents-discovered' event.
142	 */
143	export interface AgentsDiscoveredPayload {
144	  agents: AgentDefinition[];
145	}
146	
147	export interface SlashCommandConflict {
148	  name: string;
149	  renamedTo: string;
150	  loserExtensionName?: string;
151	  winnerExtensionName?: string;
152	  loserMcpServerName?: string;
153	  winnerMcpServerName?: string;
154	  loserKind?: string;
155	  winnerKind?: string;
156	}
157	
158	export interface SlashCommandConflictsPayload {
159	  conflicts: SlashCommandConflict[];
160	}
161	
162	/**
163	 * Payload for the 'quota-changed' event.
164	 */
165	export interface QuotaChangedPayload {
166	  remaining: number | undefined;
167	  limit: number | undefined;
168	  resetTime?: string;
169	}
170	
171	export enum CoreEvent {
172	  UserFeedback = 'user-feedback',
173	  ModelChanged = 'model-changed',
174	  ConsoleLog = 'console-log',
175	  Output = 'output',
176	  MemoryChanged = 'memory-changed',
177	  ExternalEditorClosed = 'external-editor-closed',
178	  McpClientUpdate = 'mcp-client-update',
179	  OauthDisplayMessage = 'oauth-display-message',
180	  SettingsChanged = 'settings-changed',
181	  HookStart = 'hook-start',
182	  HookEnd = 'hook-end',
183	  AgentsRefreshed = 'agents-refreshed',
184	  AdminSettingsChanged = 'admin-settings-changed',
185	  RetryAttempt = 'retry-attempt',
186	  ConsentRequest = 'consent-request',
187	  McpProgress = 'mcp-progress',
188	  AgentsDiscovered = 'agents-discovered',
189	  RequestEditorSelection = 'request-editor-selection',
190	  EditorSelected = 'editor-selected',
191	  SlashCommandConflicts = 'slash-command-conflicts',
192	  QuotaChanged = 'quota-changed',
193	  TelemetryKeychainAvailability = 'telemetry-keychain-availability',
194	  TelemetryTokenStorageType = 'telemetry-token-storage-type',
195	}
196	
197	/**
198	 * Payload for the 'editor-selected' event.
199	 */
200	export interface EditorSelectedPayload {
201	  editor?: EditorType;
202	}
203	
204	export interface CoreEvents extends ExtensionEvents {
205	  [CoreEvent.UserFeedback]: [UserFeedbackPayload];
206	  [CoreEvent.ModelChanged]: [ModelChangedPayload];
207	  [CoreEvent.ConsoleLog]: [ConsoleLogPayload];
208	  [CoreEvent.Output]: [OutputPayload];
209	  [CoreEvent.MemoryChanged]: [MemoryChangedPayload];
210	  [CoreEvent.QuotaChanged]: [QuotaChangedPayload];
211	  [CoreEvent.ExternalEditorClosed]: never[];
212	  [CoreEvent.McpClientUpdate]: Array<Map<string, McpClient> | never>;
213	  [CoreEvent.OauthDisplayMessage]: string[];
214	  [CoreEvent.SettingsChanged]: never[];
215	  [CoreEvent.HookStart]: [HookStartPayload];
216	  [CoreEvent.HookEnd]: [HookEndPayload];
217	  [CoreEvent.AgentsRefreshed]: never[];
218	  [CoreEvent.AdminSettingsChanged]: never[];
219	  [CoreEvent.RetryAttempt]: [RetryAttemptPayload];
220	  [CoreEvent.ConsentRequest]: [ConsentRequestPayload];
221	  [CoreEvent.McpProgress]: [McpProgressPayload];
222	  [CoreEvent.AgentsDiscovered]: [AgentsDiscoveredPayload];
223	  [CoreEvent.RequestEditorSelection]: never[];
224	  [CoreEvent.EditorSelected]: [EditorSelectedPayload];
225	  [CoreEvent.SlashCommandConflicts]: [SlashCommandConflictsPayload];
226	  [CoreEvent.TelemetryKeychainAvailability]: [KeychainAvailabilityEvent];
227	  [CoreEvent.TelemetryTokenStorageType]: [TokenStorageInitializationEvent];
228	}
229	
230	type EventBacklogItem = {
231	  [K in keyof CoreEvents]: {
232	    event: K;
233	    args: CoreEvents[K];
234	  };
235	}[keyof CoreEvents];
236	
237	export class CoreEventEmitter extends EventEmitter<CoreEvents> {
238	  private _eventBacklog: EventBacklogItem[] = [];
239	  private _backlogHead = 0;
240	  private static readonly MAX_BACKLOG_SIZE = 10000;
241	
242	  constructor() {
243	    super();
244	  }
245	
246	  private _emitOrQueue<K extends keyof CoreEvents>(
247	    event: K,
248	    ...args: CoreEvents[K]
