import * as fs from 'node:fs';
import * as path from 'node:path';
import { Storage } from '../config/storage.js';
import { CoreEvent, coreEvents } from './events.js';

/**
 * Filename of the sentinel file that records the user has acknowledged the
 * browser automation consent notice. Stored under ~/.gemini/.
 */
const BROWSER_CONSENT_FILENAME = 'browser-consent-acknowledged.txt';

/** Contents written to the sentinel file once consent is acknowledged. */
const CONSENT_ACKNOWLEDGED_CONTENT = 'consent acknowledged';

/**
 * The privacy notice shown to the user before the browser agent starts.
 */
const CONSENT_PROMPT =
  'Privacy Notice: The browser automation feature launches a Chrome ' +
  'browser and may collect usage statistics and performance data as part of ' +
  'browsing. By continuing, you acknowledge that data may be collected in ' +
  'accordance with the Google Privacy Policy ' +
  '(https://policies.google.com/privacy).\n\n' +
  'Do you want to continue?';

/**
 * Returns the absolute path to the browser consent sentinel file.
 */
function getConsentSentinelPath(): string {
  return path.join(Storage.getGlobalGeminiDir(), BROWSER_CONSENT_FILENAME);
}

/**
 * Writes the consent sentinel file, recording that the user has acknowledged
 * the browser automation privacy notice.
 */
function writeConsentSentinel(): void {
  const sentinelPath = getConsentSentinelPath();
  fs.mkdirSync(path.dirname(sentinelPath), { recursive: true });
  fs.writeFileSync(sentinelPath, CONSENT_ACKNOWLEDGED_CONTENT);
}

/**
 * Ensures the user has consented to the browser automation data collection
 * practices before the browser agent starts.
 *
 * Behavior:
 * - If the consent sentinel file already exists, returns `true` immediately.
 * - In non-interactive mode (no listeners on `coreEvents` for consent
 *   requests), consent is automatically accepted: the sentinel is written and
 *   `true` is returned without emitting a consent request.
 * - In interactive mode, a consent request is emitted. If the user accepts,
 *   the sentinel is written and `true` is returned; if the user declines, the
 *   sentinel is not written and `false` is returned.
 */
export async function getBrowserConsentIfNeeded(): Promise<boolean> {
  const sentinelPath = getConsentSentinelPath();
  if (fs.existsSync(sentinelPath)) {
    return true;
  }

  // Non-interactive mode: no UI listener to prompt the user. Auto-accept.
  if (coreEvents.listenerCount(CoreEvent.ConsentRequest) === 0) {
    writeConsentSentinel();
    return true;
  }

  // Interactive mode: ask the user via the UI.
  return new Promise<boolean>((resolve) => {
    coreEvents.emitConsentRequest({
      prompt: CONSENT_PROMPT,
      onConfirm: (confirmed: boolean) => {
        if (confirmed) {
          writeConsentSentinel();
          resolve(true);
        } else {
          resolve(false);
        }
      },
    });
  });
}
